  function slopeFor(h) {
    const t = D.slopes[String(h)];
    if (t !== undefined) return t;
    const hs = Object.keys(D.slopes).map(Number);
    return D.slopes[String(hs.reduce((b, x) => Math.abs(x - h) < Math.abs(b - h) ? x : b, hs[0]))];
  }
  const phiOf = (a) => D.phi[Math.max(25, Math.min(99, Math.round(a))) - 25];
  const heightsWithLinked = Object.keys(D.linked).map(Number).sort((a, b) => a - b);
  const heightsWithLadders = Object.keys(D.ladders).map(Number).sort((a, b) => a - b);
